public boolean checkInclusion(String s1, String s2) {
    int m = s1.length();
    if (m > s2.length()) return false;
    int[] need = new int[26], window = new int[26];
    for (char c : s1.toCharArray()) need[c - 'a']++;
    for (int i = 0; i < s2.length(); i++) {
        window[s2.charAt(i) - 'a']++;                 // letter enters on the right
        if (i >= m) window[s2.charAt(i - m) - 'a']--; // letter leaves on the left
        if (Arrays.equals(window, need)) return true; // 26 comparisons: constant
    }
    return false;
}

public String minWindow(String s, String t) {
    int[] need = new int[128];
    for (char c : t.toCharArray()) need[c]++;
    int missing = t.length();                  // required characters not yet in the window
    int left = 0, bestStart = 0, bestLen = Integer.MAX_VALUE;

    for (int right = 0; right < s.length(); right++) {
        char c = s.charAt(right);
        if (need[c] > 0) missing--;            // c was still required
        need[c]--;                             // may go negative: spare copy
        while (missing == 0) {                 // window covers t: try to shrink
            if (right - left + 1 < bestLen) {
                bestLen = right - left + 1;
                bestStart = left;
            }
            char out = s.charAt(left++);
            need[out]++;
            if (need[out] > 0) missing++;      // dropped a required character
        }
    }
    return bestLen == Integer.MAX_VALUE ? "" : s.substring(bestStart, bestStart + bestLen);
}

